-- Initial schema for Edd's Wallet, generated by `drizzle-kit generate`
-- from src/db/schema.ts and then hand-patched (this file, not the
-- generator) to add:
--   1. `STRICT` on every table (drizzle-kit's SQLite generator doesn't
--      emit it) - see data/edw-tech-research/report.md Section 3.
--   2. BEFORE UPDATE/DELETE triggers on cash_entries and credit_entries
--      that make the ledger append-only at the database engine level
--      (the block at the bottom of this file).
-- Any future `drizzle-kit generate` run for schema changes will need the
-- same two patches re-applied to its output by hand; drizzle-kit's diff
-- engine does not model STRICT or triggers.
--
-- WAL mode and `PRAGMA foreign_keys = ON` are connection-level settings,
-- not migration DDL - see src/db/connection.ts.

CREATE TABLE `accounts` (
	`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL,
	`child_user_id` integer NOT NULL,
	`currency_label` text DEFAULT 'USD' NOT NULL,
	`created_at` text NOT NULL,
	FOREIGN KEY (`child_user_id`) REFERENCES `users`(`id`) ON UPDATE no action ON DELETE no action
) STRICT;
--> statement-breakpoint
CREATE UNIQUE INDEX `accounts_child_user_id_unique` ON `accounts` (`child_user_id`);--> statement-breakpoint
CREATE TABLE `allowance_rules` (
	`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL,
	`account_id` integer NOT NULL,
	`pocket_id` integer NOT NULL,
	`amount_cents` integer NOT NULL,
	`frequency` text NOT NULL,
	`anchor_date` text NOT NULL,
	`memo` text,
	`active` integer DEFAULT 1 NOT NULL,
	`created_by_user_id` integer NOT NULL,
	`created_at` text NOT NULL,
	`updated_at` text NOT NULL,
	FOREIGN KEY (`account_id`) REFERENCES `accounts`(`id`) ON UPDATE no action ON DELETE no action,
	FOREIGN KEY (`pocket_id`) REFERENCES `pockets`(`id`) ON UPDATE no action ON DELETE no action,
	FOREIGN KEY (`created_by_user_id`) REFERENCES `users`(`id`) ON UPDATE no action ON DELETE no action,
	CONSTRAINT "allowance_rules_amount_positive" CHECK("allowance_rules"."amount_cents" > 0),
	CONSTRAINT "allowance_rules_frequency_check" CHECK("allowance_rules"."frequency" in ('weekly', 'biweekly', 'monthly'))
) STRICT;
--> statement-breakpoint
CREATE INDEX `allowance_rules_account_id_idx` ON `allowance_rules` (`account_id`);--> statement-breakpoint
CREATE TABLE `audit_log` (
	`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL,
	`actor_user_id` integer NOT NULL,
	`action` text NOT NULL,
	`entity_type` text NOT NULL,
	`entity_id` integer NOT NULL,
	`detail_json` text,
	`created_at` text NOT NULL,
	FOREIGN KEY (`actor_user_id`) REFERENCES `users`(`id`) ON UPDATE no action ON DELETE no action
) STRICT;
--> statement-breakpoint
CREATE TABLE `cash_entries` (
	`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL,
	`pocket_id` integer NOT NULL,
	`amount_cents` integer NOT NULL,
	`entry_type` text NOT NULL,
	`transfer_group_id` text,
	`source_type` text,
	`source_id` integer,
	`memo` text,
	`created_by_user_id` integer NOT NULL,
	`balance_after_cents` integer NOT NULL,
	`created_at` text NOT NULL,
	FOREIGN KEY (`pocket_id`) REFERENCES `pockets`(`id`) ON UPDATE no action ON DELETE no action,
	FOREIGN KEY (`created_by_user_id`) REFERENCES `users`(`id`) ON UPDATE no action ON DELETE no action,
	CONSTRAINT "cash_entries_amount_nonzero" CHECK("cash_entries"."amount_cents" != 0),
	CONSTRAINT "cash_entries_entry_type_check" CHECK("cash_entries"."entry_type" in ('deposit', 'withdrawal', 'allowance_payout', 'transfer_in', 'transfer_out', 'loan_disbursement', 'loan_repayment', 'credit_card_payment', 'interest_earned', 'adjustment')),
	CONSTRAINT "cash_entries_source_type_check" CHECK("cash_entries"."source_type" is null or "cash_entries"."source_type" in ('allowance_rule', 'credit_line', 'manual'))
) STRICT;
--> statement-breakpoint
CREATE INDEX `cash_entries_pocket_id_idx` ON `cash_entries` (`pocket_id`,`id`);--> statement-breakpoint
CREATE TABLE `concept_unlocks` (
	`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL,
	`account_id` integer NOT NULL,
	`concept_key` text NOT NULL,
	`unlocked_at` text,
	`unlocked_by_user_id` integer,
	FOREIGN KEY (`account_id`) REFERENCES `accounts`(`id`) ON UPDATE no action ON DELETE no action,
