	CONSTRAINT "concept_unlocks_concept_key_check" CHECK("concept_unlocks"."concept_key" in ('balance', 'allowance', 'savings_interest', 'loans', 'credit_card'))
) STRICT;
--> statement-breakpoint
CREATE UNIQUE INDEX `concept_unlocks_account_id_concept_key_unique` ON `concept_unlocks` (`account_id`,`concept_key`);--> statement-breakpoint
CREATE TABLE `credit_entries` (
	`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL,
	`credit_line_id` integer NOT NULL,
	`amount_cents` integer NOT NULL,
	`entry_type` text NOT NULL,
