CREATE INDEX `credit_entries_credit_line_id_idx` ON `credit_entries` (`credit_line_id`,`id`);--> statement-breakpoint
CREATE TABLE `credit_lines` (
	`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL,
	`account_id` integer NOT NULL,
	`kind` text NOT NULL,
	`label` text NOT NULL,
	`principal_or_limit_cents` integer NOT NULL,
	`apr_bps` integer DEFAULT 0 NOT NULL,
	`installment_amount_cents` integer,
	`installment_frequency` text,
	`statement_day` integer,
	`status` text DEFAULT 'active' NOT NULL,
	`opened_at` text NOT NULL,
	`closed_at` text,
	`created_by_user_id` integer NOT NULL,
	FOREIGN KEY (`account_id`) REFERENCES `accounts`(`id`) ON UPDATE no action ON DELETE no action,
	FOREIGN KEY (`created_by_user_id`) REFERENCES `users`(`id`) ON UPDATE no action ON DELETE no action,
	CONSTRAINT "credit_lines_kind_check" CHECK("credit_lines"."kind" in ('installment_loan', 'credit_card')),
	CONSTRAINT "credit_lines_installment_frequency_check" CHECK("credit_lines"."installment_frequency" is null or "credit_lines"."installment_frequency" in ('weekly', 'biweekly', 'monthly')),
	CONSTRAINT "credit_lines_status_check" CHECK("credit_lines"."status" in ('active', 'paid_off', 'frozen', 'forgiven'))
) STRICT;
