CREATE UNIQUE INDEX `sessions_token_hash_unique` ON `sessions` (`token_hash`);--> statement-breakpoint
CREATE TABLE `users` (
	`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL,
	`role` text NOT NULL,
	`display_name` text NOT NULL,
	`pin_hash` text,
	`pin_salt` text,
	`birth_year` integer,
	`created_at` text DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')) NOT NULL,
	`archived_at` text,
	CONSTRAINT "users_role_check" CHECK("users"."role" in ('parent', 'child', 'system'))
) STRICT;
--> statement-breakpoint
-- Append-only ledger enforcement (report Section 2/3): a bug that tried to
-- mutate or delete a historical ledger row is rejected by SQLite itself,
-- independent of any application-level check.
CREATE TRIGGER cash_entries_no_update BEFORE UPDATE ON cash_entries
BEGIN
  SELECT RAISE(ABORT, 'ledger is append-only');
END;
--> statement-breakpoint
CREATE TRIGGER cash_entries_no_delete BEFORE DELETE ON cash_entries
BEGIN
  SELECT RAISE(ABORT, 'ledger is append-only');
END;
--> statement-breakpoint
CREATE TRIGGER credit_entries_no_update BEFORE UPDATE ON credit_entries
BEGIN
  SELECT RAISE(ABORT, 'ledger is append-only');
END;
--> statement-breakpoint
CREATE TRIGGER credit_entries_no_delete BEFORE DELETE ON credit_entries
BEGIN
  SELECT RAISE(ABORT, 'ledger is append-only');
END;
